% Create a helix antenna
% Generated by MATLAB(R) 26.2 and Antenna Toolbox 26.2
%Generated on:29-Oct-2026 13:49:32

%% Antenna Properties 

antennaObject = design(helix, 1800*1e6);
antennaObject.Radius = 0.028;
antennaObject.Width = 0.0012;
antennaObject.Turns = 4;
antennaObject.Spacing = 0.035;
antennaObject.GroundPlaneRadius = 0.075;
antennaObject.Substrate.Thickness = 0.1422;
antennaObject.Load.Impedance = 72;
% Show
figure;
show(antennaObject) 

%% Antenna Analysis 
% Define plot frequency 
plotFrequency = 1.8*1e9;
% Define frequency range 
freqRange = (1790:1:2200)*1e6;
% Reference Impedance 
refImpedance = 50;
% impedance
figure;
impedance(antennaObject, freqRange)% sparameter
figure;
s = sparameters(antennaObject, freqRange, refImpedance); 
rfplot(s)% pattern
figure;
pattern(antennaObject, plotFrequency)% azimuth
figure;
patternAzimuth(antennaObject, plotFrequency, 0, 'Azimuth', 0:5:360)% elevation
figure;
patternElevation(antennaObject, plotFrequency,0,'Elevation',0:5:360)% current
figure;
current(antennaObject, plotFrequency)

